// BoundaryCodec is the optional extension this package implements on top of
// codec.StreamingCodec: the two constructors that take the boundary from the
// caller instead of recovering it from the bytes.
//
// This is the honest form of the streaming API. An HTTP server already holds
// the authoritative boundary in the request's Content-Type header, and an HTTP
// client must set that header before it writes the first body byte — neither
// can be expressed through NewEncoder / NewDecoder, whose signatures the
// domain fixes. Callers reach it with a type assertion, the same way they
// reach codec.Appender.
type BoundaryCodec interface {
	codec.Codec
	// NewEncoderWithBoundary streams a body framed by the given boundary.
	NewEncoderWithBoundary(w io.Writer, boundary string) (enc codec.Encoder, err error)
	// NewDecoderWithBoundary streams a body framed by the given boundary,
	// bypassing recovery from the wire entirely.
	NewDecoderWithBoundary(r io.Reader, boundary string) (dec codec.Decoder, err error)
}

// BoundaryProvider is implemented by the codec.Encoder this package returns,
// so a caller streaming a request body can read the generated delimiter and
// set its Content-Type header before the first byte goes out.
type BoundaryProvider interface {
	// Boundary returns the delimiter the encoder writes.
	Boundary() string
}

// FormValue is a whole multipart/form-data body: its RFC 2046 delimiter and
// its sections, in wire order.
//
// Boundary is the one field that has no equivalent in the codec.Codec
// contract, which carries no Content-Type. Empty on Marshal means "generate
// one"; Unmarshal always fills it with the delimiter it recovered, so a decode
// → encode round trip keeps the original delimiter. It reproduces the whole
// body byte for byte only for a body this package encoded, and whose
// filenames carry no path separator: a PartValue models a part's name,
// filename, media type and bytes, so any other part header — a
// Content-Transfer-Encoding, a custom one — and another producer's header
// order or casing are not carried through, and a filename is decoded to its
// last path element (see PartValue.FileName).
type FormValue struct {
	// Boundary is the RFC 2046 delimiter framing the parts.
	Boundary string
	// Parts are the body's sections, in wire order.
	Parts []PartValue
}

// PartValue is one section of a multipart/form-data body: a named field,
// optionally a filename and a media type, and the bytes themselves.
//
// The body is materialised. Streaming happens BETWEEN parts (one part per
// Encode / Decode), not inside one: codec.Decoder's Decode(v any) has nowhere
// to hand back an io.Reader the caller must drain before the next call, so a
// part body is read whole under LimitsConfig.MaxPartBytes. A consumer moving
// objects too large for that ceiling raises it with NewWithLimits, or reaches
// for mime/multipart directly — see CLAUDE.md §Not covered.
//
// Name, FileName and ContentType are written into the part's header block, so
// a CR, an LF or a NUL in any of them is refused with ValueInvalid naming the
// field: a line break there would end the header line and let the rest of the
// value write headers of its own. Nothing is escaped or repaired on the way.
type PartValue struct {
	// Name is the form field name (Content-Disposition name=). Required: Encode
	// refuses a part without one, and decoding refuses a body carrying one.
	Name string
	// FileName is the optional filename= parameter; empty for a plain field.
	// UTF-8 is written as-is (RFC 7578 §4.2); only CR, LF and NUL are refused.
	//
	// Decoding keeps only its LAST PATH ELEMENT, and reads both '/' and '\' as
	// separators on every operating system: RFC 7578 §4.2 has the receiver drop
	// the directory information a sender may include, and the sender writes it
	// with its own separator. `C:\Users\ada\cv.pdf` and `dir/cv.pdf` both
	// decode to `cv.pdf`, wherever the decoder runs. Nothing else is removed —
	// "." and ".." come back as sent — so a caller turning it into a path still
	// validates it first.
	FileName string
	// ContentType is the optional per-part media type; empty omits the header.
	ContentType string
	// Data is the part body.
	Data []byte
}

// LimitsConfig bounds what a multipart body may materialise. Every field is a
// ceiling, never a target.
//
// A ZERO field means "use this package's documented default" — never
// "unlimited" (ADR 0031: a policy's zero value is a safe default or an
// explicit refusal, never an inert policy). A NEGATIVE field is refused at
// construction with LimitsInvalid: the SDK can supply a ceiling the caller
// forgot, but it cannot tell a typo apart from a request for no ceiling at
// all, and guessing would silently remove the guard the type exists to place.
//
// There is deliberately no way to spell "unlimited". A decoder without a
// ceiling is the defect this type prevents.
type LimitsConfig struct {
	// MaxPartBytes caps a single part body; 0 selects DefaultMaxPartBytes.
	MaxPartBytes int64
	// MaxParts caps the number of parts; 0 selects DefaultMaxParts.
	MaxParts int
	// MaxTotalBytes caps the sum of part bodies; 0 selects DefaultMaxTotalBytes.
	MaxTotalBytes int64
}
